/// <reference lib="webworker" />
declare const self: ServiceWorkerGlobalScope;

import { cleanupOutdatedCaches, precacheAndRoute } from 'workbox-precaching';
import { clientsClaim } from 'workbox-core';
import { registerRoute, NavigationRoute } from 'workbox-routing';
import { CacheFirst, NetworkFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';

// Automatically precache the assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || []);

// Clean old caches
cleanupOutdatedCaches();

/*
 * A new version waits rather than seizing the open page.
 *
 * This used to call self.skipWaiting() unconditionally at the top level. The
 * effect, combined with registerType: "autoUpdate", was that every time the
 * app regained focus the browser revalidated the service worker, and if
 * anything had been deployed since, the new worker activated immediately,
 * claimed the running page, and the injected registration reloaded it. Anyone
 * who switched to their bank app and came back lost their place.
 *
 * Waiting means the update applies on the next cold start instead, which for
 * a phone app is soon enough. clientsClaim still runs so the very first
 * install controls the page without needing a reload, and the ChunkLoadError
 * handler in __root.tsx already covers the one case where a stale page really
 * must refresh: a code chunk that no longer exists on the server.
 */
clientsClaim();

// Left as an explicit opt-in, so an update can still be applied on demand
// (post {type: 'SKIP_WAITING'}) without any background reload.
self.addEventListener('message', (event) => {
  if ((event.data as any)?.type === 'SKIP_WAITING') self.skipWaiting();
  // The app answered or declined a ring (or the call ended): clear the ringing
  // notification so the phone stops showing it.
  if ((event.data as any)?.type === 'STOP_RING') {
    const url = String((event.data as any).url || '');
    event.waitUntil?.(
      self.registration.getNotifications().then((list) =>
        list.forEach((n) => { if (n.data?.ring && (!url || n.data?.url === url)) n.close(); }),
      ),
    );
  }
});

/*
 * Runtime caching. Precaching alone only covers build output; these rules make
 * repeat navigations, images and fonts fast, and keep the app usable when the
 * network drops. Live data (Supabase, server functions) is deliberately never
 * cached so members always see current information.
 */

// Pages: fast when online, still render from cache when offline.
registerRoute(
  new NavigationRoute(
    new NetworkFirst({
      cacheName: 'zc-pages',
      // Short: past this the cached page shows at once and the fresh one is
      // saved for next time. 4s left phones staring at a blank screen.
      networkTimeoutSeconds: 2,
      plugins: [new ExpirationPlugin({ maxEntries: 40, maxAgeSeconds: 60 * 60 * 24 * 7 })],
    }),
    { denylist: [/^\/api\//, /^\/_serverFn/] },
  ),
);

// Content-hashed build assets never change, so cache-first is always correct.
registerRoute(
  ({ url, request }) =>
    url.origin === self.location.origin &&
    (url.pathname.startsWith('/assets/') || request.destination === 'script' || request.destination === 'style'),
  new CacheFirst({
    cacheName: 'zc-assets',
    plugins: [new ExpirationPlugin({ maxEntries: 120, maxAgeSeconds: 60 * 60 * 24 * 30 })],
  }),
);

// Google Fonts stylesheet: from cache on every launch after the first.
registerRoute(
  ({ url }) => url.origin === 'https://fonts.googleapis.com',
  new StaleWhileRevalidate({
    cacheName: 'zc-font-css',
    plugins: [new ExpirationPlugin({ maxEntries: 8, maxAgeSeconds: 60 * 60 * 24 * 30 })],
  }),
);

// Images and fonts: show instantly from cache, refresh quietly in the background.
registerRoute(
  ({ request }) => request.destination === 'image' || request.destination === 'font',
  new StaleWhileRevalidate({
    cacheName: 'zc-media',
    plugins: [new ExpirationPlugin({ maxEntries: 80, maxAgeSeconds: 60 * 60 * 24 * 30 })],
  }),
);

// Handle incoming push events from the OS
self.addEventListener('push', (event) => {
  let payload: any = {
    title: 'Zero Club',
    body: 'You have a new notification',
    url: '/app/notifications',
  };

  try {
    if (event.data) {
      payload = event.data.json();
    }
  } catch (err) {
    if (event.data) {
      payload.body = event.data.text();
    }
  }

  // A group call or a club going live rings: a long phone-call vibration that
  // stays on screen with Join / Decline until answered.
  const ringing = payload.type === 'group_call' || payload.type === 'club_live';
  if (ringing) {
    event.waitUntil(
      self.registration.showNotification(payload.title || 'Zero Club', {
        body: payload.body,
        icon: payload.icon || '/icons/icon-192.png',
        badge: '/icons/icon-monochrome-512.png',
        vibrate: [900, 500, 900, 500, 900, 500, 900, 500, 900, 500, 900],
        requireInteraction: true,
        renotify: true,
        tag: `ring:${payload.url || payload.tag || ''}`,
        data: { url: payload.url || '/app', ring: true },
        actions: [
          { action: 'join', title: payload.type === 'club_live' ? 'Join live' : 'Join call' },
          { action: 'decline', title: 'Decline' },
        ],
      } as NotificationOptions),
    );
    return;
  }

  const options: NotificationOptions & {
    vibrate?: number[];
    actions?: { action: string; title: string; icon?: string }[];
    renotify?: boolean;
  } = {
    body: payload.body,
    // The sender's photo for messages, like chat apps; the app icon otherwise.
    icon: payload.icon || '/icons/icon-192.png',
    // Android's status bar draws the badge as a white silhouette, so it
    // needs the monochrome icon (a full-colour logo shows as a white square).
    badge: '/icons/icon-monochrome-512.png',
    vibrate: payload.type === 'game_buzz' ? [250, 80, 250, 80, 400] : [100, 50, 100],
    requireInteraction: payload.type === 'game_buzz',
    // One notification per conversation that updates as new messages arrive,
    // and still buzzes each time (renotify), the way WhatsApp behaves.
    tag: payload.type === 'game_buzz' ? `zero-game-buzz:${payload.url || ''}` : payload.tag || undefined,
    renotify: payload.type === 'game_buzz' || Boolean(payload.tag),
    data: {
      url: payload.url || '/app',
    },
    actions: [
      {
        action: 'open',
        title: payload.type === 'game_buzz' ? 'Join game' : 'Open App'
      }
    ]
  };

  event.waitUntil((async () => {
    // System notifications now drop down over other apps (Android heads-up).
    // While Zero Club itself is open and on screen, the in-app pop card already
    // shows these, so skip the system banner instead of showing two cards.
    // Club and group messages, calls and game buzzes have no in-app card and
    // always show.
    if (SHOWN_IN_APP.has(payload.type)) {
      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      if (windows.some((w) => (w as WindowClient).visibilityState === 'visible' && (w as WindowClient).focused)) return;
    }
    await self.registration.showNotification(payload.title || 'Zero Club', options);
  })());
});

/** Push types the in-app pop card (IncomingNotificationCard) also shows. */
const SHOWN_IN_APP = new Set([
  'message', 'like', 'comment_like', 'comment', 'follow', 'repost', 'mention',
  'club_mention', 'build_tagged', 'gig', 'system', 'notification',
]);

// Handle user clicking the notification: open exactly what it was about.
//
// This used to call client.navigate() without waiting for it. navigate() only
// works on a page this worker controls, and throws otherwise, so a tap often
// just brought the app forward wherever it already was instead of opening the
// chat. Now the running app is asked to route there itself (instant, no
// reload), with a full navigation and then a new window as fallbacks.
self.addEventListener('notificationclick', (event) => {
  // The ongoing-call notification stays up for the whole call: on Android it
  // keeps the microphone service running (features/calls/backgroundCall.ts).
  if (!event.notification.data?.ongoingCall) event.notification.close();
  // Declining a ring just dismisses it.
  if (event.action === 'decline') return;

  const target = new URL(event.notification.data?.url || '/app', self.location.origin).href;

  const askAppToRoute = (client: WindowClient) =>
    new Promise<boolean>((resolve) => {
      const channel = new MessageChannel();
      const timer = setTimeout(() => resolve(false), 1500);
      channel.port1.onmessage = () => {
        clearTimeout(timer);
        resolve(true);
      };
      client.postMessage({ type: 'NOTIFICATION_NAVIGATE', url: target }, [channel.port2]);
    });

  event.waitUntil((async () => {
    const windows = (await self.clients.matchAll({ type: 'window', includeUncontrolled: true })) as WindowClient[];
    const sameOrigin = windows.filter((c) => new URL(c.url).origin === self.location.origin);
    // Prefer the window the person was last looking at.
    const client = sameOrigin.find((c) => c.focused) || sameOrigin.find((c) => c.visibilityState === 'visible') || sameOrigin[0];

    if (client) {
      // Focus first, while the tap still counts as a user gesture.
      const focused = await client.focus().catch(() => client);
      if (await askAppToRoute(focused)) return;
      try {
        if (await focused.navigate(target)) return;
      } catch {
        /* Not controlled by this worker; open a fresh window instead. */
      }
    }

    await self.clients.openWindow(target);
  })());
});

